use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut k: int = 0
    let mut first = true
    let mut cur = ""
    let mut body = ""
    for line in text.lines() {
        if first {
            k = line.trim().parse::<int>().unwrap_or(0)
            first = false
        } else {
            body = body + line + "\n"
        }
    }
    for c in body.chars() {
        if c.is_ascii_alphanumeric() {
            cur = cur + c.to_ascii_lowercase().to_string()
        } else {
            if cur.len() > 0 {
                let n = counts.get(&cur).copied().unwrap_or(0)
                counts.insert(cur, n + 1)
                cur = ""
            }
        }
    }
    if cur.len() > 0 {
        let n = counts.get(&cur).copied().unwrap_or(0)
        counts.insert(cur, n + 1)
    }
    let mut items: Vec<(string, int)> = Vec::new()
    for (w, n) in counts {
        items.push((w, n))
    }
    items.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(&a.1)
        } else {
            a.0.cmp(&b.0)
        }
    })
    let mut i: int = 0
    for it in items {
        if i >= k {
            break
        }
        println("{} {}", it.0, it.1)
        i = i + 1
    }
}
